  "applicable_norms": [
    {
      "policy_source_id": "q15",
      "interpretation": "Agents may, but are not required to, mention the loyalty discount (10% for subscribers older than 5 years). There is no obligation to apply it or push it as a mandatory offer.",
      "modality": "PERMIT"
    },
    {
      "policy_source_id": "q15",
      "interpretation": "Agents must not claim an action succeeded if the tool returned an error or if the user did not explicitly confirm changes (e.g., plan changes, roaming packs).",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q15",
      "interpretation": "Communication must be accurate and aligned with the user's intent. Unprompted offers of discounts or changes must not mislead or assume user intent.",
      "modality": "REQUIRE"
    }
  ],
  "supporting_evidence": [
    {
      "source_id": "h35",
      "actor": "user",
      "role": "requester",
      "fact": "User asked about current payment and potential savings, but did not explicitly request a loyalty discount or plan change."
    },
    {
      "source_id": "h4",
      "actor": "system",
      "role": "subscriber_data",
      "fact": "User has been a subscriber since 2016-05-01, qualifying for the loyalty discount."
    },
